def transform(grid):
    a=[row[:] for row in grid]
    h,w=len(a),len(a[0]); bg=grid[0][0]
    seen=set()
    for r in range(h):
      for c in range(w):
        color=a[r][c]
        if color==bg or (r,c) in seen: continue
        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            q=(y+dy,x+dx)
            if 0<=q[0]<h and 0<=q[1]<w and q not in seen and a[q[0]][q[1]]==color:
              seen.add(q); stack.append(q)
        r0=min(y for y,x in comp); r1=max(y for y,x in comp); c0=min(x for y,x in comp); c1=max(x for y,x in comp)
        if r1-r0<2 or c1-c0<2: continue
        if all(a[r0][x]==color for x in range(c0,c1+1)) and all(a[r1][x]==color for x in range(c0,c1+1)) and all(a[y][c0]==color and a[y][c1]==color for y in range(r0,r1+1)):
          cells=[(y,x) for y in range(r0+1,r1) for x in range(c0+1,c1) if a[y][x]==bg]
          val=7 if (r1-r0-1)%2==1 else 2
          for y,x in cells: a[y][x]=val
    return a
